B.aJC=new A.a("\u0643\u0627\u0646 \u0627\u0644\u0646\u0628\u064a \ufdfa \u064a\u0642\u062a\u062f\u064a \u0628\u0627\u0644\u0623\u0646\u0628\u064a\u0627\u0621 \u0648\u0627\u0644\u0645\u0631\u0633\u0644\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u0633\u0628\u0642\u0648\u0647 \u0641\u064a \u0627\u0644\u062f\u0639\u0648\u0629 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647\u060c \u0641\u0647\u0630\u0627 \u0646\u0648\u062d \u0644\u0628\u062b \u0641\u064a \u0642\u0648\u0645\u0647 \u062f\u0627\u0639\u064a\u064b\u0627: \u0623\u064e\u0644\u0652\u0641\u064e \u0633\u064e\u0646\u064e\u0629\u064d \u0625\u0650\u0644\u0627\u0651\u064e \u062e\u064e\u0645\u0652\u0633\u0650\u064a\u0646\u064e \u0639\u064e\u0627\u0645\u064b\u0627 - \u0633\u0648\u0631\u0629 \u0627\u0644\u0639\u0646\u0643\u0628\u0648\u062a \u0641\u0643\u0627\u0646\u062a \u0647\u0630\u0647 \u0627\u0644\u0623\u0639\u0648\u0627\u0645 \u0627\u0644\u0637\u0648\u064a\u0644\u0629 \u0639\u0645\u0644\u0627\u064b \u062f\u0627\u0626\u0628\u064b\u0627\u060c \u0648\u062a\u0646\u0648\u064a\u0639\u064b\u0627 \u0645\u062a\u0643\u0631\u0631\u064b\u0627 \u060c \u0642\u0627\u0644 \u062a\u0639\u0627\u0644\u0649: \u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0625\u0650\u0646\u0651\u0650\u064a \u062f\u064e\u0639\u064e\u0648\u0652\u062a\u064f \u0642\u064e\u0648\u0652\u0645\u0650\u064a \u0644\u064e\u064a\u0652\u0644\u0627\u064b \u0648\u064e\u0646\u064e\u0647\u064e\u0627\u0631\u064b\u0627 - \u0641\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0632\u0650\u062f\u0652\u0647\u064f\u0645\u0652 \u062f\u064f\u0639\u064e\u0627\u0626\u0650\u064a \u0625\u0650\u0644\u0627\u0651\u064e \u0641\u0650\u0631\u064e\u0627\u0631\u064b\u0627 - \u0648\u064e\u0625\u0650\u0646\u0651\u0650\u064a \u0643\u064f\u0644\u0651\u064e\u0645\u064e\u0627 \u062f\u064e\u0639\u064e\u0648\u0652\u062a\u064f\u0647\u064f\u0645\u0652 \u0644\u0650\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u062c\u064e\u0639\u064e\u0644\u064f\u0648\u0627 \u0623\u064e\u0635\u064e\u0627\u0628\u0650\u0639\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0622\u0630\u064e\u0627\u0646\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0627\u0633\u0652\u062a\u064e\u063a\u0652\u0634\u064e\u0648\u0652\u0627 \u062b\u0650\u064a\u064e\u0627\u0628\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0635\u064e\u0631\u0651\u064f\u0648\u0627 \u0648\u064e\u0627\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u064e\u0631\u064f\u0648\u0627 \u0627\u0633\u0652\u062a\u0650\u0643\u0652\u0628\u064e\u0627\u0631\u064b\u0627 - \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u062f\u064e\u0639\u064e\u0648\u0652\u062a\u064f\u0647\u064f\u0645\u0652 \u062c\u0650\u0647\u064e\u0627\u0631\u064b\u0627 - \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u0639\u0652\u0644\u064e\u0646\u0652\u062a\u064f \u0644\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0633\u0652\u0631\u064e\u0631\u0652\u062a\u064f \u0644\u064e\u0647\u064f\u0645\u0652 \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0631\u064b\u0627 - \u0633\u0648\u0631\u0629 \u0646\u0648\u062d",null)
B.aRS=new A.a("\u0648\u0645\u0639 \u0627\u0645\u062a\u062f\u0627\u062f \u0627\u0644\u0632\u0645\u0646 \u0627\u0644\u0637\u0648\u064a\u0644 \u0645\u0627 \u062a\u0648\u0642\u0641 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0639\u0646 \u0627\u0644\u062f\u0639\u0648\u0629\u060c \u0648\u0644\u0627 \u0636\u0639\u064f\u0641\u062a \u0647\u0645\u062a\u0647 \u0641\u064a \u062a\u0628\u0644\u064a\u063a\u0647\u0627\u060c \u0648\u0644\u0627 \u0636\u0639\u064f\u0641\u062a \u0628\u0635\u064a\u0631\u062a\u0647 \u0648\u062d\u064a\u0644\u062a\u0647 \u0641\u064a \u062a\u0646\u0648\u064a\u0639 \u0623\u0648\u0642\u0627\u062a\u0647\u0627 \u0648\u0623\u0633\u0627\u0644\u064a\u0628\u0647\u0627\u060c \u0641\u0643\u0627\u0646 \u0627\u0644\u0646\u0628\u064a \ufdfa \u064a\u0646\u0648\u0639 \u0648\u064a\u0628\u062a\u0643\u0631 \u0641\u064a \u0623\u0633\u0627\u0644\u064a\u0628 \u0627\u0644\u062f\u0639\u0648\u0629\u060c \u0648\u062f\u0639\u0627 \u0633\u0631\u064b\u0627 \u0648\u062c\u0647\u0631\u064b\u0627\u060c \u0648\u0633\u0644\u0645\u064b\u0627 \u0648\u062d\u0631\u0628\u064b\u0627\u060c \u0648\u062c\u0645\u0639\u064b\u0627\u060c \u0648\u0641\u0631\u062f\u064b\u0627\u060c \u0648\u0633\u0641\u0631\u064b\u0627 \u0648\u062d\u0636\u0631\u064b\u0627\u060c \u0643\u0645\u0627 \u0623\u0646\u0647 \u0639\u0644\u064a\u0647 \u0627\u0644\u0635\u0644\u0627\u0629 \u0648\u0627\u0644\u0633\u0644\u0627\u0645 \u0642\u0635 \u0627\u0644\u0642\u0635\u0635\u060c \u0648\u0636\u0631\u0628 \u0627\u0644\u0623\u0645\u062b\u0627\u0644\u060c \u0648\u0627\u0633\u062a\u062e\u062f\u0645 \u0648\u0633\u0627\u0626\u0644 \u0627\u0644\u0625\u064a\u0636\u0627\u062d \u0628\u0627\u0644\u062e\u0637 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0648\u063a\u064a\u0631\u0647\u060c \u0643\u0645\u0627 \u0631\u063a\u0628 \u0648\u0628\u0634\u0631\u060c \u0648\u0631\u0647\u0628 \u0648\u0623\u0646\u0630\u0631\u060c \u0648\u062f\u0639\u0627 \u0641\u064a \u0643\u0644 \u0622\u0646\u064d\u060c \u0648\u0639\u0644\u0649 \u0643\u0644 \u062d\u0627\u0644 \u0648\u0628\u0643\u0644 \u0623\u0633\u0644\u0648\u0628 \u0645\u0624\u062b\u0631 \u0641\u0639\u0651\u064e\u0627\u0644  \u0641\u0647\u0627 \u0647\u0648 \u0639\u0644\u064a\u0647 \u0627\u0644\u0635\u0644\u0627\u0629 \u0648\u0627\u0644\u0633\u0644\u0627\u0645 \u064a\u0646\u062a\u0642\u0644 \u0625\u0644\u0649 \u0627\u0644\u0637\u0627\u0626\u0641\u060c \u062b\u0645 \u064a\u062a\u0631\u062f\u062f \u0639\u0644\u0649 \u0627\u0644\u0642\u0628\u0627\u0626\u0644\u060c \u062b\u0645 \u064a\u0647\u0627\u062c\u0631 \u0648\u064a\u0633\u062a\u0645\u0631 \u0641\u064a \u062f\u0639\u0648\u0629 \u0627\u0644\u062e\u0644\u0642 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649.",null)
