B.azt=new A.a("\u0644\u0645\u0627 \u0628\u0644\u063a \u0627\u0644\u0646\u0628\u064a \ufdfa \u0646\u062c\u0627\u0629 \u0627\u0644\u0642\u0627\u0641\u0644\u0629 \u0648\u0625\u0635\u0631\u0627\u0631 \u0632\u0639\u0645\u0627\u0621 \u0645\u0643\u0629 \u0639\u0644\u0649 \u0642\u062a\u0627\u0644 \u0627\u0644\u0646\u0628\u064a \ufdfa \u060c \u0627\u0633\u062a\u0634\u0627\u0631 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0623\u0635\u062d\u0627\u0628\u0647 \u0641\u064a \u0627\u0644\u0623\u0645\u0631 \u0648\u0623\u0628\u062f\u0649 \u0628\u0639\u0636 \u0627\u0644\u0635\u062d\u0627\u0628\u0629 \u0639\u062f\u0645 \u0627\u0631\u062a\u064a\u0627\u062d\u0647\u0645 \u0644\u0645\u0633\u0623\u0644\u0629 \u0627\u0644\u0645\u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u062d\u0631\u0628\u064a\u0629 \u0645\u0639 \u0642\u0631\u064a\u0634 \u062d\u064a\u062b \u0623\u0646\u0647\u0645 \u0644\u0645 \u064a\u062a\u0648\u0642\u0639\u0648\u0627 \u0627\u0644\u0645\u0648\u0627\u062c\u0647\u0629 \u0648\u0644\u0645 \u064a\u0633\u062a\u0639\u062f\u0648\u0627 \u0644\u0647\u0627 \u0648\u062d\u0627\u0648\u0644\u0648\u0627 \u0627\u0642\u0646\u0627\u0639 \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa \u0628\u0648\u062c\u0647\u0629 \u0646\u0638\u0631\u0647\u0645\u060c \u0648\u0642\u062f \u0635\u0648\u0631 \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0643\u0631\u064a\u0645 \u0645\u0648\u0642\u0641\u0647\u0645 \u0648\u0623\u062d\u0648\u0627\u0644 \u0627\u0644\u0641\u0626\u0629 \u0627\u0644\u0645\u0624\u0645\u0646\u0629 \u0639\u0645\u0648\u0645\u0627\u064b \u0641\u064a \u0642\u0648\u0644\u0647 \u062a\u0639\u0627\u0644\u0649: \u0643\u064e\u0645\u064e\u0627 \u0623\u064e\u062e\u0652\u0631\u064e\u062c\u064e\u0643\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0645\u0650\u0646\u0652 \u0628\u064e\u064a\u0652\u062a\u0650\u0643\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0641\u064e\u0631\u0650\u064a\u0642\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0644\u064e\u0643\u064e\u0627\u0631\u0650\u0647\u064f\u0648\u0646\u064e \u064a\u064f\u062c\u064e\u0627\u062f\u0650\u0644\u064f\u0648\u0646\u064e\u0643\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0628\u064e\u0639\u0652\u062f\u064e\u0645\u064e\u0627 \u062a\u064e\u0628\u064e\u064a\u0651\u064e\u0646\u064e \u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064f\u0633\u064e\u0627\u0642\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u0650 \u0648\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0646\u0652\u0638\u064f\u0631\u064f\u0648\u0646\u064e \u0648\u064e\u0625\u0650\u0630\u0652 \u064a\u064e\u0639\u0650\u062f\u064f\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0625\u0650\u062d\u0652\u062f\u064e\u0649 \u0627\u0644\u0637\u0651\u064e\u0627\u0626\u0650\u0641\u064e\u062a\u064e\u064a\u0652\u0646\u0650 \u0623\u064e\u0646\u0651\u064e\u0647\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u062a\u064e\u0648\u064e\u062f\u0651\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0651\u064e \u063a\u064e\u064a\u0652\u0631\u064e \u0630\u064e\u0627\u062a\u0650 \u0627\u0644\u0634\u0651\u064e\u0648\u0652\u0643\u064e\u0629\u0650 \u062a\u064e\u0643\u064f\u0648\u0646\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0646\u0652 \u064a\u064f\u062d\u0650\u0642\u0651\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064e \u0628\u0650\u0643\u064e\u0644\u0650\u0645\u064e\u0627\u062a\u0650\u0647\u0650 \u0648\u064e\u064a\u064e\u0642\u0652\u0637\u064e\u0639\u064e \u062f\u064e\u0627\u0628\u0650\u0631\u064e \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0644\u0650\u064a\u064f\u062d\u0650\u0642\u0651\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064e \u0648\u064e\u064a\u064f\u0628\u0652\u0637\u0650\u0644\u064e \u0627\u0644\u0652\u0628\u064e\u0627\u0637\u0650\u0644\u064e \u0648\u064e\u0644\u064e\u0648\u0652 \u0643\u064e\u0631\u0650\u0647\u064e \u0627\u0644\u0652\u0645\u064f\u062c\u0652\u0631\u0650\u0645\u064f\u0648\u0646\u064e - \u0633\u0648\u0631\u0629 \u0627\u0644\u0623\u0646\u0641\u0627\u0644",null)
B.aDd=new A.a("\u0648\u0642\u062f \u0623\u062c\u0645\u0639 \u0642\u0627\u062f\u0629 \u0627\u0644\u0645\u0647\u0627\u062c\u0631\u064a\u0646 \u0639\u0644\u0649 \u062a\u0623\u064a\u064a\u062f \u0641\u0643\u0631\u0629 \u0627\u0644\u062a\u0642\u062f\u0645 \u0644\u0645\u0644\u0627\u0642\u0627\u0629 \u0627\u0644\u0639\u062f\u0648 \u0648\u0643\u0627\u0646 \u0644\u0644\u0645\u0642\u062f\u0627\u062f \u0628\u0646 \u0627\u0644\u0623\u0633\u0648\u062f \u0645\u0648\u0642\u0641\u0627\u064b \u0645\u062a\u0645\u064a\u0632\u0627\u064b \u0641\u0642\u062f \u0642\u0627\u0644 \u0639\u0628\u062f\u0627\u0644\u0644\u0647 \u0628\u0646 \u0645\u0633\u0639\u0648\u062f \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647: \u0634\u0647\u062f\u062a \u0645\u0646 \u0627\u0644\u0645\u0642\u062f\u0627\u062f \u0628\u0646 \u0627\u0644\u0623\u0633\u0648\u062f \u0645\u0634\u0647\u062f\u0627\u064b \u0644\u0623\u0646 \u0623\u0643\u0648\u0646 \u0635\u0627\u062d\u0628\u0647 \u0623\u062d\u0628 \u0625\u0644\u064a\u0651\u064e \u0645\u0645\u0627 \u0639\u064f\u062f\u0650\u0644\u064e \u0628\u0647 \u0623\u062a\u0649 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0648\u0647\u0648 \u064a\u062f\u0639\u0648 \u0639\u0644\u0649 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0641\u0642\u0627\u0644: \u0644\u0627\u0646\u0642\u0648\u0644 \u0643\u0645\u0627 \u0642\u0627\u0644 \u0642\u0648\u0645 \u0645\u0648\u0633\u0649: \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u064a\u064e\u0627\u0645\u064f\u0648\u0633\u064e\u0649 \u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0646\u0652 \u0646\u064e\u062f\u0652\u062e\u064f\u0644\u064e\u0647\u064e\u0627 \u0623\u064e\u0628\u064e\u062f\u064b\u0627 \u0645\u064e\u0627 \u062f\u064e\u0627\u0645\u064f\u0648\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0641\u064e\u0627\u0630\u0652\u0647\u064e\u0628\u0652 \u0623\u064e\u0646\u0652\u062a\u064e \u0648\u064e\u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0641\u064e\u0642\u064e\u0627\u062a\u0650\u0644\u0627 \u0625\u0650\u0646\u0651\u064e\u0627\u0647\u064e\u0627\u0647\u064f\u0646\u064e\u0627 \u0642\u064e\u0627\u0639\u0650\u062f\u064f\u0648\u0646\u064e - \u0633\u0648\u0631\u0629 \u0627\u0644\u0645\u0627\u0626\u062f\u0629 \u060c \u0648\u0644\u0643\u0646 \u0646\u0642\u0627\u062a\u0644 \u0639\u0646 \u064a\u0645\u064a\u0646\u0643 \u0648\u0639\u0646 \u0634\u0645\u0627\u0644\u0643 \u0648\u0628\u064a\u0646 \u064a\u062f\u064a\u0643 \u0648\u062e\u0644\u0641\u0643 .",null)
