B.ay1=new A.a("\u0648\u0628\u0639\u062f \u0630\u0644\u0643 \u0639\u0627\u062f \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0641\u0642\u0627\u0644: \u0623\u0634\u064a\u0631\u0648\u0627 \u0639\u0644\u064a\u0651\u064e \u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0627\u0633\u060c \u0648\u0643\u0627\u0646 \u0625\u0646\u0645\u0627 \u064a\u0642\u0635\u062f \u0627\u0644\u0623\u0646\u0635\u0627\u0631 \u0644\u0623\u0646\u0647\u0645 \u063a\u0627\u0644\u0628\u064a\u0629 \u062c\u0646\u062f\u0647\u060c \u0648\u0644\u0623\u0646 \u0628\u064a\u0639\u0629 \u0627\u0644\u0639\u0642\u0628\u0629 \u0627\u0644\u062b\u0627\u0646\u064a\u0629 \u0644\u0645 \u062a\u0643\u0646 \u0641\u064a \u0638\u0627\u0647\u0631\u0647\u0627 \u0645\u0644\u0632\u0645\u0629 \u0644\u0647\u0645 \u0628\u062d\u0645\u0627\u064a\u0629 \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa \u062e\u0627\u0631\u062c \u0627\u0644\u0645\u062f\u064a\u0646\u0629\u060c \u0648\u0642\u062f \u0623\u062f\u0631\u0643 \u0627\u0644\u0635\u062d\u0627\u0628\u064a \u0633\u0639\u062f \u0628\u0646 \u0645\u0639\u0627\u0630 \u0648\u0647\u0648 \u062d\u0627\u0645\u0644 \u0644\u0648\u0627\u0621 \u0627\u0644\u0627\u0646\u0635\u0627\u0631 \u0645\u0642\u0635\u062f \u0627\u0644\u0646\u0628\u064a \ufdfa \u0645\u0646 \u0630\u0644\u0643 \u0641\u0646\u0647\u0636 \u0642\u0627\u0626\u0644\u0627\u064b: \u0648\u0627\u0644\u0644\u0647 \u0644\u0650\u0643\u064e\u0627\u0646\u0643 \u062a\u064f\u0631\u0650\u064a\u062f\u0646\u064e\u0627 \u064a\u064e\u0627\u0631\u0633\u064f\u0648\u0644 \u0627\u0644\u0644\u0647\u061f \u0642\u0627\u0644 \ufdfa \u0623\u062c\u0644\u060c \u0642\u0627\u0644: \u064a\u0627 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0644\u0642\u062f \u0622\u0645\u0646\u0627 \u0628\u0643 \u0648\u0635\u062f\u0642\u0646\u0627\u0643 \u0648\u0634\u0647\u062f\u0646\u0627 \u0623\u0646 \u0645\u0627\u062c\u0626\u062a \u0628\u0647 \u0647\u0648 \u0627\u0644\u062d\u0642 \u0648\u0623\u0639\u0637\u064a\u0646\u0627\u0643 \u0639\u0644\u0649 \u0630\u0644\u0643 \u0639\u0647\u0648\u062f\u0646\u0627 \u0648\u0645\u0648\u0627\u062b\u064a\u0642\u0646\u0627 \u0639\u0644\u0649 \u0627\u0644\u0633\u0645\u0639 \u0648\u0627\u0644\u0637\u0627\u0639\u0629\u060c \u0641\u0627\u0645\u0636\u064a \u064a\u0627 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0644\u0645\u0627 \u0623\u0631\u062f\u062a\u060c \u0641\u0648 \u0627\u0644\u0630\u064a \u0628\u0639\u062b\u0643 \u0628\u0627\u0644\u062d\u0642 \u0644\u0648 \u0627\u0633\u062a\u0639\u0631\u0636\u062a \u0628\u0646\u0627 \u0647\u0630\u0627 \u0627\u0644\u0628\u062d\u0631 \u0641\u062e\u0636\u062a\u0647 \u0644\u062e\u0636\u0646\u0627\u0647 \u0645\u0639\u0643 \u0645\u0627\u062a\u062e\u0644\u0641 \u0645\u0646\u0627 \u0631\u062c\u0644 \u0648\u0627\u062d\u062f \u0648\u0645\u0627\u0646\u0643\u0631\u0647 \u0623\u0646 \u062a\u0644\u0642\u0649 \u0628\u0646\u0627 \u0639\u062f\u0648\u0651\u0646\u0627 \u063a\u062f\u0627\u064b\u060c \u0648\u0625\u0646\u064e\u0651\u0627 \u0644\u0635\u064e\u0628\u0631 \u0641\u064a \u0627\u0644\u062d\u0631\u0628 \u0635\u062f\u0642 \u0639\u0646\u062f \u0627\u0644\u0644\u0642\u0627\u0621 \u0648\u0644\u0639\u0644 \u0627\u0644\u0644\u0647 \u064a\u0631\u064a\u0643 \u0645\u0646\u0627 \u0645\u0627 \u062a\u0642\u0631\u0651 \u0628\u0647 \u0639\u064a\u0646\u0643 \u0641\u0633\u0631 \u0639\u0644\u0649 \u0628\u0631\u0643\u0629 \u0627\u0644\u0644\u0647.",null)
B.aQz=new A.a("\u0648\u0633\u064f\u0631\u0651 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0645\u0646 \u0645\u0642\u0627\u0644\u0629 \u0633\u0639\u062f \u0628\u0646 \u0645\u0639\u0627\u0630 \u0648\u0646\u0634\u0637\u0647 \u0630\u0644\u0643 \u0641\u0642\u0627\u0644 \ufdfa : \u0633\u064a\u0631\u0648\u0627 \u0648\u0623\u0628\u0634\u0631\u0648\u0627 \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0642\u062f \u0648\u0639\u062f\u0646\u064a \u0625\u062d\u062f\u0649 \u0627\u0644\u0637\u0627\u0626\u0641\u062a\u064a\u0646 \u0648\u0627\u0644\u0644\u0647 \u0644\u0643\u0623\u0646\u064a \u0623\u0646\u0638\u0631 \u0627\u0644\u0649 \u0645\u0635\u0627\u0631\u0639 \u0627\u0644\u0642\u0648\u0645.",null)
