B.aJd=new A.a("\u0648\u0642\u062f \u062a\u062d\u062f\u062b \u0627\u0628\u0646 \u0639\u0628\u0627\u0633 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0641\u0642\u0627\u0644: \u0625\u0646 \u0648\u0641\u062f \u0639\u0628\u062f \u0627\u0644\u0642\u064a\u0633 \u0623\u062a\u0648\u0627 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0641\u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0645\u0646 \u0627\u0644\u0648\u0641\u062f\u061f \u0623\u0648 \u0645\u0646 \u0627\u0644\u0642\u0648\u0645\u061f \u0642\u0627\u0644\u0648\u0627: \u0631\u0628\u064a\u0639\u0629 \u0642\u0627\u0644: \u0645\u0631\u062d\u0628\u0627\u064b \u0628\u0627\u0644\u0642\u0648\u0645 \u0623\u0648 \u0628\u0627\u0644\u0648\u0641\u062f \u063a\u064a\u0631 \u062e\u0632\u0627\u064a\u0627 \u0648\u0644\u0627 \u0627\u0644\u0646\u062f\u0627\u0645\u0649 \u0642\u0627\u0644: \u0641\u0642\u0627\u0644\u0648\u0627: \u064a\u0627\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647: \u0625\u0646\u0627 \u0646\u0623\u062a\u064a\u0643 \u0645\u0646 \u0634\u0642\u0629 \u0628\u0639\u064a\u062f\u0629 \u0648\u0625\u0646 \u0628\u064a\u0646\u0646\u0627 \u0648\u0628\u064a\u0646\u0643 \u0647\u0630\u0627 \u0627\u0644\u062d\u064a \u0645\u0646 \u0643\u0641\u0627\u0631 \u0645\u0636\u0631 \u0648\u0625\u0646\u0627 \u0644\u0627\u0646\u0633\u062a\u0637\u064a\u0639 \u0623\u0646 \u0646\u0623\u062a\u064a\u0643 \u0625\u0644\u0627 \u0641\u064a \u0634\u0647\u0631 \u062d\u0631\u0627\u0645\u060c \u0641\u0645\u0631\u0646\u0627 \u0628\u0623\u0645\u0631 \u0641\u0635\u0644 \u0646\u062e\u0628\u0631 \u0628\u0647 \u0645\u0646 \u0648\u0631\u0627\u0621\u0646\u0627 \u0646\u062f\u062e\u0644 \u0628\u0647 \u0627\u0644\u062c\u0646\u0629 \u0642\u0627\u0644: \u0641\u0623\u0645\u0631\u0647\u0645 \u0628\u0623\u0631\u0628\u0639 \u0648\u0646\u0647\u0627\u0647\u0645 \u0639\u0646 \u0623\u0631\u0628\u0639\u060c \u0642\u0627\u0644: \u0623\u0645\u0631\u0647\u0645 \u0628\u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0627\u0644\u0644\u0647 \u0648\u062d\u062f\u0647 \u0642\u0627\u0644: \u0647\u0644 \u062a\u062f\u0631\u0648\u0646 \u0645\u0627 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0627\u0644\u0644\u0647\u061f \u0642\u0627\u0644\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0623\u0639\u0644\u0645 \u0642\u0627\u0644: \u0634\u0647\u0627\u062f\u0629 \u0623\u0646 \u0644\u0627 \u0625\u0644\u0647 \u0625\u0644\u0627 \u0627\u0644\u0644\u0647 \u0648\u0623\u0646 \u0645\u062d\u0645\u062f\u0627\u064b \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0648\u0625\u0642\u0627\u0645 \u0627\u0644\u0635\u0644\u0627\u0629 \u0648\u0625\u064a\u062a\u0627\u0621 \u0627\u0644\u0632\u0643\u0627\u0629 \u0648\u0635\u0648\u0645 \u0631\u0645\u0636\u0627\u0646 \u0648\u0623\u0646 \u062a\u0624\u062f\u0648\u0627 \u062e\u0645\u0633\u0627\u064b \u0645\u0646 \u0627\u0644\u0645\u063a\u0646\u0645 \u0648\u0646\u0647\u0627\u0647\u0645 \u0639\u0646 \u0627\u0644\u062f\u0628\u0627\u0621 -\u0627\u0644\u0642\u0631\u0639 \u0627\u0644\u064a\u0627\u0628\u0633- \u0648\u0627\u0644\u062d\u0646\u062a\u0645 -\u062c\u0631\u0627\u0631 \u064a\u062d\u0645\u0644 \u0641\u064a\u0647\u0627 \u0627\u0644\u062e\u0645\u0631- \u0648\u0627\u0644\u0645\u0632\u0641\u062a -\u0627\u0644\u0623\u0648\u0639\u064a\u0629 \u0627\u0644\u062a\u064a \u0641\u064a\u0647\u0627 \u0627\u0644\u0632\u0641\u062a- \u0648\u0628\u0645\u0627 \u0642\u0627\u0644 \u0627\u0644\u0646\u0642\u064a\u0631 \u0623\u0648 \u0627\u0644\u0645\u0642\u064a\u0631 -\u062c\u0630\u0639 \u064a\u0646\u0642\u0631 \u0648\u0633\u0637\u0647 \u062b\u0645 \u064a\u0646\u0628\u0630 \u0641\u064a\u0647\u0627 \u0627\u0644\u0631\u0637\u0628 \u0648\u0627\u0644\u0628\u0633\u0631- \u0648\u0642\u0627\u0644: \u0627\u062d\u0641\u0638\u0648\u0647 \u0648\u0623\u062e\u0628\u0631\u0648\u0627 \u0628\u0647 \u0645\u0646 \u0648\u0631\u0627\u0621\u0643\u0645\u060c \u0648\u0641\u064a \u0631\u0648\u0627\u064a\u0629: \u0623\u0646 \u0627\u0644\u0627\u0634\u062c \u0628\u0646 \u0639\u0628\u062f \u0642\u064a\u0633 \u062a\u062e\u0644\u0641 \u0641\u064a \u0627\u0644\u0631\u0643\u0627\u0628 \u062d\u062a\u0649 \u0623\u0646\u0627\u062e\u0647\u0627 \u0648\u062c\u0645\u0639 \u0645\u062a\u0627\u0639 \u0627\u0644\u0642\u0648\u0645 \u062b\u0645 \u062c\u0627\u0621 \u064a\u0645\u0634\u064a \u062d\u062a\u0649 \u0623\u062e\u0630 \u0628\u064a\u062f \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0641\u0642\u0628\u0644\u0647\u0627 \u0641\u0642\u0627\u0644 \u0644\u0647 \u0627\u0644\u0646\u0628\u064a \ufdfa : \u0625\u0646 \u0641\u064a\u0643 \u062e\u0644\u062a\u064a\u0646 \u064a\u062d\u0628\u0647\u0645\u0627 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0641\u0642\u0627\u0644: \u062c\u0628\u0644 \u062c\u0628\u0644\u062a \u0639\u0644\u064a\u0647 \u0623\u0645 \u062a\u062e\u0644\u0642\u0627\u064b \u0645\u0646\u064a\u061f \u0642\u0627\u0644: \u0628\u0644 \u062c\u0628\u0644\u064c \u0642\u0627\u0644: \u0627\u0644\u062d\u0645\u062f \u0644\u0644\u0647 \u0627\u0644\u0630\u064a \u062c\u0628\u0644\u0646\u064a \u0639\u0644\u0649 \u0645\u0627\u064a\u062d\u0628 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u060c \u0648\u0642\u062f \u0627\u0646\u0634\u063a\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0628\u0645\u0642\u062f\u0645\u0647\u0645 \u0648\u0623\u062e\u0631 \u0635\u0644\u0627\u0629 \u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0628\u0639\u062f\u064a\u0629 \u0628\u0639\u062f \u0627\u0644\u0638\u0647\u0631 \u0648\u0635\u0644\u0627\u0647\u0627 \u0628\u0639\u062f \u0627\u0644\u0639\u0635\u0631.",null)
