B.azL=new A.a("\u0627\u0628\u062a\u064f\u0644\u064a \u0627\u0644\u0639\u0631\u0628 \u0628\u062a\u062e\u0644\u0641 \u062f\u064a\u0646\u064a \u0634\u062f\u064a\u062f\u060c \u0648\u0648\u062b\u0646\u064a\u0629 \u0633\u062e\u064a\u0641\u0629 \u0644\u0627 \u0645\u062b\u064a\u0644 \u0644\u0647\u0627\u060c \u0648\u0627\u0646\u062d\u0631\u0627\u0641\u0627\u062a \u062e\u0644\u0642\u064a\u0629\u060c \u0648\u0627\u062c\u062a\u0645\u0627\u0639\u064a\u0629\u060c \u0648\u0641\u0648\u0636\u0649 \u0633\u064a\u0627\u0633\u064a\u0629 \u0648\u062a\u0634\u0631\u064a\u0639\u064a\u0629\u060c \u0648\u0645\u0646 \u062b\u0645 \u0642\u0644 \u0634\u0623\u0646\u0647\u0645 \u0648\u0635\u0627\u0631\u0648\u0627 \u064a\u0639\u064a\u0634\u0648\u0646 \u0639\u0644\u0649 \u0647\u0627\u0645\u0634 \u0627\u0644\u062a\u0627\u0631\u064a\u062e\u060c \u0648\u0644\u0627 \u064a\u062a\u0639\u062f\u0648\u0646 \u0641\u064a \u0623\u062d\u0633\u0646 \u0627\u0644\u0623\u062d\u0648\u0627\u0644 \u0623\u0646 \u064a\u0643\u0648\u0646\u0648\u0627 \u062a\u0627\u0628\u0639\u064a\u0646 \u0644\u0644\u062f\u0648\u0644\u0629 \u0627\u0644\u0641\u0627\u0631\u0633\u064a\u0629 \u0623\u0648 \u0627\u0644\u0631\u0648\u0645\u0627\u0646\u064a\u0629\u060c \u0648\u0642\u062f \u0627\u0645\u062a\u0644\u0623\u062a \u0642\u0644\u0648\u0628\u0647\u0645 \u0628\u062a\u0639\u0638\u064a\u0645 \u062a\u0631\u0627\u062b \u0627\u0644\u0622\u0628\u0627\u0621 \u0648\u0627\u0644\u0623\u062c\u062f\u0627\u062f \u0648\u0627\u062a\u0628\u0627\u0639 \u0645\u0627 \u0643\u0627\u0646\u0648\u0627 \u0639\u0644\u064a\u0647 \u0645\u0647\u0645\u0627 \u064a\u0643\u0646 \u0641\u064a\u0647 \u0645\u0646 \u0627\u0644\u0632\u064a\u063a \u0648\u0627\u0644\u0627\u0646\u062d\u0631\u0627\u0641 \u0648\u0627\u0644\u0636\u0644\u0627\u0644 \u0648\u0645\u0646 \u062b\u0645 \u0639\u0628\u062f\u0648\u0627 \u0627\u0644\u0623\u0635\u0646\u0627\u0645\u060c \u0641\u0643\u0627\u0646 \u0644\u0643\u0644 \u0642\u0628\u064a\u0644\u0629 \u0635\u0646\u0645\u060c \u0641\u0643\u0627\u0646 \u0644\u0647\u0630\u064a\u0644 \u0628\u0646 \u0645\u062f\u0631\u0643\u0629: \u0633\u0648\u0627\u0639\u060c \u0648\u0644\u0643\u0644\u0628: \u0648\u062f\u060c \u0648\u0644\u0645\u0630\u062d\u062c: \u064a\u063a\u0648\u062b\u060c \u0648\u0644\u062e\u064a\u0648\u0627\u0646: \u064a\u0639\u0648\u0642\u060c \u0648\u0644\u062d\u0645\u064a\u0631: \u0646\u0633\u0631\u060c \u0648\u0643\u0627\u0646\u062a \u062e\u0632\u0627\u0639\u0629 \u0648\u0642\u0631\u064a\u0634 \u062a\u0639\u0628\u062f \u0625\u0633\u0627\u0641\u064b\u0627 \u0648\u0646\u0627\u0626\u0644\u0629\u060c \u0648\u0643\u0627\u0646\u062a \u0645\u0646\u0627\u0629 \u0639\u0644\u0649 \u0633\u0627\u062d\u0644 \u0627\u0644\u0628\u062d\u0631\u060c \u062a\u0639\u0638\u0645\u0647\u0627 \u0627\u0644\u0639\u0631\u0628 \u0643\u0627\u0641\u0629 \u0648\u0627\u0644\u0623\u0648\u0633 \u0648\u0627\u0644\u062e\u0632\u0631\u062c \u062e\u0627\u0635\u0629\u060c \u0648\u0643\u0627\u0646\u062a \u0627\u0644\u0644\u0627\u062a \u0641\u064a \u062b\u0642\u064a\u0641\u060c \u0648\u0643\u0627\u0646\u062a \u0627\u0644\u0639\u0632\u0649 \u0641\u0648\u0642 \u0630\u0627\u062a \u0639\u0631\u0642\u060c \u0648\u0643\u0627\u0646\u062a \u0623\u0639\u0638\u0645 \u0627\u0644\u0623\u0635\u0646\u0627\u0645 \u0639\u0646\u062f \u0642\u0631\u064a\u0634.",null)
B.aEm=new A.a("\u0648\u0643\u0627\u0646 \u0627\u0644\u0646\u0638\u0627\u0645 \u0627\u0644\u0633\u0627\u0626\u062f \u0641\u0649 \u0627\u0644\u062c\u0632\u064a\u0631\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629 \u0647\u0648 \u0627\u0644\u0646\u0638\u0627\u0645 \u0627\u0644\u0642\u0628\u0644\u064a\u060c \u0648\u0643\u0627\u0646 \u064a\u0646\u0642\u0633\u0645\u0648\u0646 \u0625\u0644\u0649 \u0628\u062f\u0648 \u0648\u062d\u0636\u0631\u060c \u062d\u062a\u0649 \u0641\u064a \u0627\u0644\u0645\u0645\u0627\u0644\u0643 \u0627\u0644\u0645\u062a\u062d\u0636\u0631\u0629 \u0627\u0644\u062a\u064a \u0646\u0634\u0623\u062a \u0628\u0627\u0644\u062c\u0632\u064a\u0631\u0629\u060c \u0643\u0645\u0645\u0644\u0643\u0629 \u0627\u0644\u064a\u0645\u0646 \u0641\u064a \u0627\u0644\u062c\u0646\u0648\u0628 \u0648\u0645\u0645\u0644\u0643\u0629 \u0627\u0644\u062d\u064a\u0631\u0629 \u0641\u064a \u0627\u0644\u0634\u0645\u0627\u0644 \u0627\u0644\u0634\u0631\u0642\u064a\u060c \u0648\u0645\u0645\u0644\u0643\u0629 \u0627\u0644\u063a\u0633\u0627\u0633\u0646\u0629 \u0641\u064a \u0627\u0644\u0634\u0645\u0627\u0644 \u0627\u0644\u063a\u0631\u0628\u064a\u060c \u0641\u0644\u0645 \u062a\u0646\u0635\u0647\u0631 \u0627\u0644\u062c\u0645\u0627\u0639\u0629 \u0641\u064a\u0647\u0627 \u0641\u064a \u0634\u0639\u0628 \u0648\u0627\u062d\u062f\u060c \u0648\u0625\u0646\u0645\u0627 \u0638\u0644\u062a \u0627\u0644\u0642\u0628\u0627\u0626\u0644 \u0648\u062d\u062f\u0627\u062a \u0645\u062a\u0645\u0627\u0633\u0643\u0629.",null)
B.ay3=new A.a("\u0648\u0627\u0644\u0642\u0628\u064a\u0644\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629 \u0645\u062c\u0645\u0648\u0639\u0629 \u0645\u0646 \u0627\u0644\u0646\u0627\u0633\u060c \u062a\u0631\u0628\u0637 \u0628\u064a\u0646\u0647\u0627 \u0648\u062d\u062f\u0629 \u0627\u0644\u0646\u0633\u0628 \u0648\u0648\u062d\u062f\u0629 \u0627\u0644\u062c\u0645\u0627\u0639\u0629\u060c \u0648\u0641\u064a \u0638\u0644 \u0647\u0630\u0647 \u0627\u0644\u0631\u0627\u0628\u0637\u0629 \u0646\u0634\u0623 \u0642\u0627\u0646\u0648\u0646 \u0639\u0631\u0641\u064a \u064a\u0646\u0638\u0645 \u0627\u0644\u0639\u0644\u0627\u0642\u0627\u062a \u0628\u064a\u0646 \u0627\u0644\u0641\u0631\u062f \u0648\u0627\u0644\u062c\u0645\u0627\u0639\u0629\u060c \u0639\u0644\u0649 \u0623\u0633\u0627\u0633 \u0645\u0646 \u0627\u0644\u062a\u0636\u0627\u0645\u0646 \u0628\u064a\u0646\u0647\u0645\u0627 \u0641\u064a \u0627\u0644\u062d\u0642\u0648\u0642 \u0648\u0627\u0644\u0648\u0627\u062c\u0628\u0627\u062a\u060c \u0648\u0647\u0630\u0627 \u0627\u0644\u0642\u0627\u0646\u0648\u0646 \u0627\u0644\u0639\u0631\u0641\u064a \u0643\u0627\u0646\u062a \u062a\u062a\u0645\u0633\u0643 \u0628\u0647 \u0627\u0644\u0642\u0628\u064a\u0644\u0629 \u0641\u064a \u0646\u0638\u0627\u0645\u0647\u0627 \u0627\u0644\u0633\u064a\u0627\u0633\u064a \u0648\u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639\u064a\u060c \u0648\u0632\u0639\u064a\u0645 \u0627\u0644\u0642\u0628\u064a\u0644\u0629 \u062a\u0631\u0634\u062d\u0647 \u0644\u0644\u0642\u064a\u0627\u062f\u0629 \u0645\u0646\u0632\u0644\u062a\u0647 \u0627\u0644\u0642\u0628\u0644\u064a\u0629 \u0648\u0635\u0641\u0627\u062a\u0647\u060c \u0648\u062e\u0635\u0627\u0626\u0635\u0647 \u0645\u0646 \u0634\u062c\u0627\u0639\u0629 \u0648\u0645\u0631\u0648\u0621\u0629\u060c \u0648\u0643\u0631\u0645 \u0648\u0646\u062d\u0648\u0647\u0627.",null)
