B.aYr=new A.a("\u0625\u0646\u0647 \u0627\u0644\u0645\u0646\u0647\u062c \u0627\u0644\u0630\u064a \u0647\u062f\u0649 \u0627\u0644\u0644\u0647 \u0646\u0628\u064a\u0647 \u0625\u0644\u0649 \u0627\u0644\u062a\u0632\u0627\u0645\u0647\u060c \u0641\u0641\u064a \u0627\u0644\u0628\u064a\u0639\u0629 \u0627\u0644\u0623\u0648\u0644\u0649 \u0628\u0627\u064a\u0639\u0647 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0623\u0646\u0635\u0627\u0631 \u0627\u0644\u062c\u062f\u062f \u0639\u0644\u0649 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0639\u0642\u064a\u062f\u0629 \u0648\u0645\u0646\u0647\u0627\u062c\u064b\u0627 \u0648\u062a\u0631\u0628\u064a\u0629\u060c \u0648\u0641\u064a \u0627\u0644\u0628\u064a\u0639\u0629 \u0627\u0644\u062b\u0627\u0646\u064a\u0629 \u0628\u0627\u064a\u0639\u0647 \u0627\u0644\u0623\u0646\u0635\u0627\u0631 \u0639\u0644\u0649 \u062d\u0645\u0627\u064a\u0629 \u0627\u0644\u062f\u0639\u0648\u0629 \u0648\u0627\u062d\u062a\u0636\u0627\u0646 \u0627\u0644\u0645\u062c\u062a\u0645\u0639 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u064a \u0627\u0644\u0630\u064a \u0646\u0636\u062c\u062a \u062b\u0645\u0627\u0631\u0647 \u0648\u0627\u0634\u062a\u062f\u062a \u0642\u0648\u0627\u0639\u062f\u0647 \u0642\u0648\u0629 \u0648\u0635\u0644\u0627\u0628\u0629.",null)
B.aTC=new A.a("\u0625\u0646 \u0647\u0627\u062a\u064a\u0646 \u0627\u0644\u0628\u064a\u0639\u062a\u064a\u0646 \u0623\u0645\u0631\u0627\u0646 \u0645\u062a\u0643\u0627\u0645\u0644\u0627\u0646 \u0636\u0645\u0646 \u0627\u0644\u0645\u0646\u0647\u062c \u0627\u0644\u062a\u0631\u0628\u0648\u064a \u0644\u0644\u062f\u0639\u0648\u0629 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u064a\u0629\u060c \u0648\u0625\u0646 \u0627\u0644\u0623\u0645\u0631 \u0627\u0644\u0623\u0648\u0644 \u0647\u0648 \u0627\u0644\u0645\u0636\u0645\u0648\u0646\u060c \u0648\u0627\u0644\u0623\u0645\u0631 \u0627\u0644\u062b\u0627\u0646\u064a\u060c \u0648\u0647\u0648 \u0628\u064a\u0639\u0629 \u0627\u0644\u062d\u0631\u0628\u060c \u0647\u0648 \u0627\u0644\u0633\u064a\u0627\u062c \u0627\u0644\u0630\u064a \u064a\u062d\u0645\u064a \u0630\u0644\u0643 \u0627\u0644\u0645\u0636\u0645\u0648\u0646\u060c \u0646\u0639\u0645 \u0643\u0627\u0646\u062a \u0628\u064a\u0639\u0629 \u0627\u0644\u062d\u0631\u0628 \u0628\u0639\u062f \u0639\u0627\u0645\u064a\u0646 \u0645\u0646 \u0625\u0639\u0644\u0627\u0646 \u0627\u0644\u0642\u0648\u0645 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0648\u0644\u064a\u0633 \u0641\u0648\u0631 \u0625\u0639\u0644\u0627\u0646\u0647\u0645.",null)
