B.aRW=new A.a("\u0641\u0644\u0645\u0627 \u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647 \u0647\u0630\u0627 \u0641\u064a \u0628\u0631\u0627\u0621\u062a\u064a\u060c \u0642\u0627\u0644 \u0623\u0628\u0648 \u0628\u0643\u0631 \u0627\u0644\u0635\u062f\u064a\u0642 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u060c \u0648\u0643\u0627\u0646 \u064a\u0646\u0641\u0642 \u0639\u0644\u0649 \u0645\u0633\u0637\u062d \u0628\u0646 \u0623\u062b\u0627\u062b\u0629 \u0644\u0642\u0631\u0627\u0628\u062a\u0647 \u0645\u0646\u0647 \u0648\u0641\u0642\u0631\u0647: \u0648\u0627\u0644\u0644\u0647 \u0644\u0627\u0623\u0646\u0641\u0642 \u0639\u0644\u0649 \u0645\u0633\u0637\u062d \u0634\u064a\u0626\u0627\u064b \u0623\u0628\u062f\u0627\u064b \u0628\u0639\u062f \u0627\u0644\u0630\u064a \u0642\u0627\u0644 \u0644\u0639\u0627\u0626\u0634\u0629 \u0645\u0627\u0642\u0627\u0644\u060c \u0641\u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647: \u0648\u064e\u0644\u0627 \u064a\u064e\u0623\u0652\u062a\u064e\u0644\u0650 \u0623\u064f\u0648\u0644\u064f\u0648 \u0627\u0644\u0652\u0641\u064e\u0636\u0652\u0644\u0650 \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0627\u0644\u0633\u0651\u064e\u0639\u064e\u0629\u0650 \u0623\u064e\u0646\u0652 \u064a\u064f\u0624\u0652\u062a\u064f\u0648\u0627 \u0623\u064f\u0648\u0644\u0650\u064a \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0628\u064e\u0649 \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u0633\u064e\u0627\u0643\u0650\u064a\u0646\u064e \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0647\u064e\u0627\u062c\u0650\u0631\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u0652\u064a\u064e\u0639\u0652\u0641\u064f\u0648\u0627 \u0648\u064e\u0644\u0652\u064a\u064e\u0635\u0652\u0641\u064e\u062d\u064f\u0648\u0627 \u0623\u064e\u0644\u0627 \u062a\u064f\u062d\u0650\u0628\u0651\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0652 \u064a\u064e\u063a\u0652\u0641\u0650\u0631\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u064e\u062d\u0650\u064a\u0645\u064c - \u0633\u0648\u0631\u0629 \u0627\u0644\u0646\u0648\u0631 \u060c \u0641\u0642\u0627\u0644 \u0623\u0628\u0648 \u0628\u0643\u0631: \u0628\u0644\u0649 \u0648\u0627\u0644\u0644\u0647 \u0625\u0646\u064a \u0623\u062d\u0628 \u0623\u0646 \u064a\u063a\u0641\u0631 \u0627\u0644\u0644\u0647 \u0644\u064a\u060c \u0641\u0623\u0631\u062c\u0639 \u0625\u0644\u0649 \u0645\u0633\u0637\u062d \u0627\u0644\u0646\u0641\u0642\u0629 \u0627\u0644\u062a\u064a \u0643\u0627\u0646 \u064a\u0646\u0641\u0642 \u0639\u0644\u064a\u0647\u060c \u0648\u0642\u0627\u0644 \u0648\u0627\u0644\u0644\u0647 \u0644\u0627\u0623\u0646\u0632\u0639\u0647\u0627 \u0645\u0646\u0647 \u0623\u0628\u062f\u0627\u064b\u060c \u0648\u0642\u0627\u0644\u062a \u0639\u0627\u0626\u0634\u0629: \u0648\u0643\u0627\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u064a\u0633\u0623\u0644 \u0632\u064a\u0646\u0628 \u0628\u0646\u062a \u062c\u062d\u0634 \u0639\u0646 \u0623\u0645\u0631\u064a\u060c \u0641\u0642\u0627\u0644: \u064a\u0627\u0632\u064a\u0646\u0628 \u0645\u0627\u0630\u0627 \u0639\u0644\u0645\u062a \u0623\u0648 \u0631\u0623\u064a\u062a\u061f\u060c \u0641\u0642\u0627\u0644\u062a: \u064a\u0627\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0623\u062d\u0645\u064a \u0633\u0645\u0639\u064a \u0648\u0628\u0635\u0631\u064a\u060c \u0648\u0645\u0627\u0639\u0644\u0645\u062a \u0625\u0644\u0627 \u062e\u064a\u0631\u0627\u064b\u060c \u0642\u0627\u0644\u062a: \u0648\u0647\u064a \u0627\u0644\u062a\u064a \u0643\u0627\u0646\u062a \u062a\u0633\u0627\u0645\u064a\u0646\u064a -\u062a\u0639\u0627\u0644\u064a\u0646\u064a \u0648\u062a\u0641\u0627\u062e\u0631\u0646\u064a- \u0645\u0646 \u0623\u0632\u0648\u0627\u062c \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0641\u0639\u0635\u0645\u0647\u0627 \u0627\u0644\u0644\u0647 \u0628\u0627\u0644\u0648\u0631\u0639 \u0648\u0637\u0641\u0642\u062a -\u0634\u0631\u0639\u062a- \u0623\u062e\u062a\u0647\u0627 \u062d\u0645\u0646\u0629 \u062a\u062d\u0627\u0631\u0628 \u0644\u0647\u0627\u060c \u0641\u0647\u0644\u0643\u062a \u0645\u0645\u0646 \u0647\u0644\u0643 \u0645\u0646 \u0623\u0635\u062d\u0627\u0628 \u0627\u0644\u0625\u0641\u0643.",null)
