B.aSW=new A.a("\u0642\u0627\u0644 \u0639\u0628\u062f\u0627\u0644\u0644\u0647 \u0628\u0646 \u0627\u0644\u0632\u0628\u064a\u0631 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647: \u0642\u0627\u0644\u062a \u0623\u0645 \u062d\u0643\u064a\u0645 \u0627\u0645\u0631\u0623\u0629 \u0639\u0643\u0631\u0645\u0629 \u0628\u0646 \u0623\u0628\u064a \u062c\u0647\u0644: \u064a\u0627\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0642\u062f \u0647\u0631\u0628 \u0639\u0643\u0631\u0645\u0629 \u0645\u0646\u0643 \u0627\u0644\u0649 \u0627\u0644\u064a\u0645\u0646\u060c \u0648\u062e\u0627\u0641 \u0623\u0646 \u062a\u0642\u062a\u0644\u0647 \u0641\u0623\u0645\u0651\u064e\u0646\u0647 \u0641\u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0647\u0648 \u0622\u0645\u0646 \u0641\u062e\u0631\u062c\u062a \u0623\u0645 \u062d\u0643\u064a\u0645 \u0641\u064a \u0637\u0644\u0628\u0647 \u0648\u0645\u0639\u0647\u0627 \u063a\u0644\u0627\u0645 \u0644\u0647\u0627 \u0631\u0648\u0645\u064a\u0651 \u0641\u0631\u0627\u0648\u062f\u0647\u0627 \u0639\u0646 \u0646\u0641\u0633\u0647\u0627\u060c \u0641\u062c\u0639\u0644\u062a \u062a\u0645\u0646\u064a\u0647 \u062d\u062a\u0649 \u0642\u062f\u0645\u062a \u0639\u0644\u0649 \u062d\u064e\u064a\u0651\u0650 \u0645\u0646 \u0639\u064e\u0643\u0651 \u0641\u0627\u0633\u062a\u063a\u062b\u062a\u0647\u0645 \u0639\u0644\u064a\u0647 \u0641\u0623\u0648\u062b\u0642\u0648\u0647 \u0631\u0628\u0627\u0637\u0627\u064b\u060c \u0648\u0623\u062f\u0631\u0643\u062a \u0639\u0643\u0631\u0645\u0629 \u0648\u0642\u062f \u0627\u0646\u062a\u0647\u0649 \u0627\u0644\u0649 \u0633\u0627\u062d\u0644 \u0645\u0646 \u0633\u0648\u0627\u062d\u0644 \u062a\u0647\u0627\u0645\u0629 \u0641\u0631\u0643\u0628 \u0627\u0644\u0628\u062d\u0631\u060c \u0641\u062c\u0639\u0644 \u0646\u064f\u0648\u062a\u064a\u0651\u064f \u0627\u0644\u0633\u0641\u064a\u0646\u0629 \u064a\u0642\u0648\u0644 \u0644\u0647: \u0623\u062e\u0644\u0635 \u0641\u0642\u0627\u0644: \u0623\u064a \u0634\u064a\u0621 \u0623\u0642\u0648\u0644: \u0642\u0627\u0644: \u0642\u0644 \u0644\u0627 \u0625\u0644\u0647 \u0625\u0644\u0627 \u0627\u0644\u0644\u0647\u060c \u0642\u0627\u0644 \u0639\u0643\u0631\u0645\u0629: \u0645\u0627\u0647\u0631\u0628\u062a \u0625\u0644\u0627 \u0645\u0646 \u0647\u0630\u0627\u060c \u0641\u062c\u0627\u0621\u062a \u0623\u0645 \u062d\u0643\u064a\u0645 \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u0643\u0644\u0627\u0645 \u0641\u062c\u0639\u0644\u062a \u062a\u0644\u062d \u0639\u0644\u064a\u0647 \u0648\u062a\u0642\u0648\u0644: \u064a\u0627 \u0627\u0628\u0646 \u0639\u0645 \u062c\u0626\u062a\u0643 \u0645\u0646 \u0639\u0646\u062f \u0623\u0648\u0635\u0644 \u0627\u0644\u0646\u0627\u0633 \u0648\u0623\u0628\u0631 \u0627\u0644\u0646\u0627\u0633 \u0648\u062e\u064a\u0631 \u0627\u0644\u0646\u0627\u0633 \u0644\u0627 \u062a\u064f\u0647\u0644\u0643 \u0646\u0641\u0633\u0643\u060c \u0641\u0648\u0642\u0641 \u0644\u0647\u0627 \u062d\u062a\u0649 \u0623\u062f\u0631\u0643\u062a\u0647 \u0641\u0642\u0627\u0644\u062a: \u0625\u0646\u064a \u0642\u062f \u0623\u0633\u062a\u0623\u0645\u0646\u062a \u0644\u0643 \u0645\u062d\u0645\u062f\u0627\u064b \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u060c \u0642\u0627\u0644: \u0623\u0646\u062a \u0641\u0639\u0644\u062a\u061f \u0642\u0627\u0644\u062a: \u0646\u0639\u0645 \u0623\u0646\u0627 \u0643\u0644\u0645\u062a\u0647 \u0641\u0623\u0645\u0646\u0651\u064e\u0643 \u0641\u0631\u062c\u0639 \u0645\u0639\u0647\u0627 \u0648\u0642\u0627\u0644: \u0645\u0627 \u0644\u0642\u064a\u062a \u0645\u0646 \u063a\u0644\u0627\u0645\u0643 \u0627\u0644\u0631\u0648\u0645\u064a\u061f \u0641\u062e\u0628\u0631\u062a\u0647 \u062e\u0628\u0631\u0647 \u0641\u0642\u062a\u0644\u0647 \u0639\u0643\u0631\u0645\u0629 \u0648\u0647\u0648 \u064a\u0624\u0645\u0626\u0630 \u0644\u0645 \u064a\u064f\u0633\u0644\u0645\u060c \u0641\u0644\u0645\u0627 \u062f\u0646\u0627 \u0645\u0646 \u0645\u0643\u0629 \u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0644\u0623\u0635\u062d\u0627\u0628\u0647: \u064a\u0623\u062a\u064a\u0643\u0645 \u0639\u0643\u0631\u0645\u0629 \u0628\u0646 \u0627\u0628\u064a \u062c\u0647\u0644 \u0645\u0624\u0645\u0646\u0627\u064b \u0645\u0647\u0627\u062c\u0631\u0627\u064b \u0641\u0644\u0627 \u062a\u064e\u0633\u064f\u0628\u0651\u0648\u0627 \u0623\u0628\u0627\u0647 \u0641\u0625\u0646 \u0633\u0628\u0651 \u0627\u0644\u0645\u064a\u062a \u064a\u0624\u0630\u064a \u0627\u0644\u062d\u064a \u0648\u0644\u0627\u064a\u0628\u0644\u063a \u0627\u0644\u0645\u064a\u062a.",null)
B.azX=new A.a("\u0642\u0627\u0644: \u0648\u062c\u0639\u0644 \u0639\u0643\u0631\u0645\u0629 \u064a\u0637\u0644\u0628 \u0627\u0645\u0631\u0623\u062a\u0647 \u064a\u064f\u062c\u0627\u0645\u0639\u0647\u0627\u060c \u0641\u062a\u0623\u0628\u0649 \u0639\u0644\u064a\u0647 \u0648\u062a\u0642\u0648\u0644: \u0625\u0646\u0643 \u0643\u0627\u0641\u0631 \u0648\u0623\u0646\u0627 \u0645\u0633\u0644\u0645\u0629 \u0641\u064a\u0642\u0648\u0644: \u0625\u0646 \u0623\u0645\u0631\u0627\u064b \u0645\u0646\u0639\u0643 \u0645\u0646\u064a \u0644\u0623\u0645\u0631 \u0643\u0628\u064a\u0631\u060c \u0641\u0644\u0645\u0627 \u0631\u0623\u0649 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0639\u0643\u0631\u0645\u0629 \u0648\u062b\u0628 \u0625\u0644\u064a\u0647 - \u0648\u0645\u0627 \u0639\u0644\u0649 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0631\u062f\u0627\u0621 - \u0641\u0631\u062d\u0627\u064b \u0628\u0639\u0643\u0631\u0645\u0629 \u062b\u0645 \u062c\u0644\u0633 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0641\u0648\u0642\u0641 \u0628\u064a\u0646 \u064a\u062f\u064a\u0647 \u0648\u0632\u0648\u062c\u062a\u0647 \u0645\u064f\u062a\u0646\u0642\u0628\u0629 \u0641\u0642\u0627\u0644: \u064a\u0627\u0645\u062d\u0645\u062f \u0625\u0646 \u0647\u0630\u0647 \u0623\u062e\u0628\u0631\u062a\u0646\u064a \u0623\u0646\u0643 \u0623\u0645\u0651\u064e\u0646\u062a\u0646\u064a\u060c \u0641\u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa : \u0635\u062f\u0642\u062a \u0641\u0623\u0646\u062a \u0622\u0645\u0646 \u0641\u0642\u0627\u0644 \u0639\u0643\u0631\u0645\u0629: \u0641\u0625\u0644\u0649 \u0645\u0627 \u062a\u062f\u0639\u0648 \u064a\u0627\u0645\u062d\u0645\u062f\u061f \u0642\u0627\u0644: \u0623\u062f\u0639\u0648\u0643 \u0627\u0644\u0649 \u0623\u0646 \u062a\u0634\u0647\u062f \u0623\u0646 \u0644\u0627 \u0625\u0644\u0647 \u0625\u0644\u0627 \u0627\u0644\u0644\u0647 \u0648\u0623\u0646\u064a \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0648\u0623\u0646 \u062a\u0642\u064a\u0645 \u0627\u0644\u0635\u0644\u0627\u0629 \u0648\u062a\u0624\u062a\u064a \u0627\u0644\u0632\u0643\u0627\u0629 \u0648\u062a\u0641\u0639\u0644 \u0648\u062a\u0641\u0639\u0644\u060c \u062d\u062a\u0649 \u0639\u062f\u0651 \u062e\u0635\u0627\u0644 \u0627\u0644\u0627\u0633\u0644\u0627\u0645\u060c \u0641\u0642\u0627\u0644 \u0639\u0643\u0631\u0645\u0629: \u0648\u0627\u0644\u0644\u0647 \u0645\u0627\u062f\u0639\u0648\u062a \u0625\u0644\u0627 \u0627\u0644\u0649 \u0627\u0644\u062d\u0642 \u0648\u0623\u0645\u0631 \u062d\u0633\u0646 \u062c\u0645\u064a\u0644\u060c \u0642\u062f \u0643\u0646\u062a \u0648\u0627\u0644\u0644\u0647 \u0641\u064a\u0646\u0627 \u0642\u0628\u0644 \u0623\u0646 \u062a\u062f\u0639\u0648 \u0627\u0644\u0649 \u0645\u0627\u062f\u0639\u0648\u062a \u0625\u0644\u064a\u0647 \u0648\u0623\u0646\u062a \u0623\u0635\u062f\u0642\u0646\u0627 \u062d\u062f\u064a\u062b\u0627\u064b \u0648\u0623\u0628\u0631\u0651\u064f\u0646\u0627 \u0628\u0631\u0651\u0627\u060c \u062b\u0645 \u0642\u0627\u0644 \u0639\u0643\u0631\u0645\u0629: \u0641\u0625\u0646\u064a \u0623\u0634\u0647\u062f \u0623\u0646 \u0644\u0627 \u0625\u0644\u0647 \u0625\u0644\u0627 \u0627\u0644\u0644\u0647 \u0648\u0623\u0634\u0647\u062f \u0623\u0646 \u0645\u062d\u0645\u062f\u0627\u064b \u0639\u0628\u062f\u0647 \u0648\u0631\u0633\u0648\u0644\u0647\u060c \u0641\u0633\u064f\u0631\u0651 \u0628\u0630\u0644\u0643 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u062b\u0645 \u0642\u0627\u0644: \u064a\u0627\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0639\u0644\u0645\u0646\u064a \u062e\u064a\u0631\u064e \u0634\u064a\u0621 \u0623\u0642\u0648\u0644\u0647 \u0641\u0642\u0627\u0644: \u062a\u0642\u0648\u0644 \u0623\u0634\u0647\u062f \u0623\u0646 \u0644\u0627 \u0625\u0644\u0647 \u0625\u0644\u0627 \u0627\u0644\u0644\u0647 \u0648\u0623\u0646 \u0645\u062d\u0645\u062f \u0639\u0628\u062f\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0641\u0642\u0627\u0644 \u0639\u0643\u0631\u0645\u0629: \u062b\u0645 \u0645\u0627\u0630\u0627\u061f \u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa : \u062a\u0642\u0648\u0644 \u0623\u0634\u0647\u062f \u0627\u0644\u0644\u0647 \u0648\u0623\u0634\u0647\u062f \u0645\u0646 \u062d\u0636\u0631 \u0623\u0646\u064a \u0645\u0633\u0644\u0645 \u0645\u0647\u0627\u062c\u0631 \u0648\u0645\u062c\u0627\u0647\u062f \u0641\u0642\u0627\u0644 \u0639\u0643\u0631\u0645\u0629 \u0630\u0644\u0643.",null)
